        reader = csv.DictReader(io.StringIO(csv_text))
        # Strip whitespace from header names, e.g. "team, goals, penalties".
        if reader.fieldnames:
            reader.fieldnames = [name.strip() for name in reader.fieldnames]
        for row in reader:
            total_goals += _to_number(row.get('goals'))
            total_penalties += _to_number(row.get('penalties'))

    # Add the extra numbers from the dicts.
