import json


def count_words_in_json(json_string):
    """
    Parse a JSON string containing an object with a "text" field and return
    a dict mapping each lowercase word to the number of times it appears.

    - Words are split on whitespace.
    - Non-alphanumeric characters are removed from each word
      (so "don't" -> "dont", "Hello!" -> "hello").
    - Tokens that become empty after removing punctuation are ignored.
    - Invalid JSON, a non-object top-level value, a missing "text" field,
      or a non-string "text" value all result in an empty dict.
    """
    try:
        data = json.loads(json_string)
    except (json.JSONDecodeError, TypeError):
        return {}

    if not isinstance(data, dict) or "text" not in data:
        return {}

    text = data["text"]
    if not isinstance(text, str):
        return {}

    counts = {}
    for token in text.split():
        word = "".join(ch for ch in token if ch.isalnum()).lower()
        if word:
            counts[word] = counts.get(word, 0) + 1

    return counts


if __name__ == "__main__":
