import json
from collections import Counter


def count_words_in_json(json_string):
    """
    Parse a JSON string holding an object with a "text" field and count
    the words in that text.

    - Words are separated by whitespace.
    - Words are compared case-insensitively and returned in lowercase.
    - Non-alphanumeric characters are deleted from each word,
      so "don't" counts as "dont" and "world!" counts as "world".
    - Tokens made only of punctuation (e.g. "--") are not counted.
    - Returns {} if the input isn't valid JSON, isn't a JSON object,
      has no "text" field, or "text" isn't a string.
    """
    try:
        data = json.loads(json_string)
    except (ValueError, TypeError, RecursionError):
        # ValueError covers json.JSONDecodeError. TypeError covers
        # non-string input such as None.
        return {}

    if not isinstance(data, dict):
        return {}

    text = data.get("text")
    if not isinstance(text, str):
        return {}

    counts = Counter()
    for token in text.split():
        word = "".join(ch for ch in token.lower() if ch.isalnum())
        if word:
            counts[word] += 1

    return dict(counts)
