        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError(
                f"Decoded value for key {key!r} is not valid UTF-8: {exc}"
            ) from exc

        result[key] = unicodedata.normalize("NFC", text)

    return result


if __name__ == "__main__":
    print(decode_base64_json_values(
        '{"key1": "SGVsbG8gV29ybGQ=", "key2": "Y2Fmw6k="}'
    ))
    # {'key1': 'Hello World', 'key2': 'café'}

    # Decomposed "café" (e + combining acute) is normalized to the composed form
    decomposed = base64.b64encode("cafe\u0301".encode()).decode()
    out = decode_base64_json_values(json.dumps({"k": decomposed}))
    assert out["k"] == "caf\u00e9"

    for bad in ['not json', '[1, 2]', '{"k": "!!!"}', '{"k": "abc"}', '{"k": 5}']:
        try:
            decode_base64_json_values(bad)
        except ValueError as e:
            print("ValueError:", e)
```

Notes:
- `validate=True` makes base64 decoding strict. Without it, `b64decode` silently discards invalid characters.
- Non-ASCII characters in a value can never be valid base64. They are caught via `UnicodeEncodeError` and reported as a `ValueError`.
- Decoded bytes that aren't valid UTF-8 also raise `ValueError`, since the spec says the values are UTF-8 strings.
- If the top level of the JSON is something other than an object (for example an array), or a value is something other than a string, the function raises `ValueError`.
- NFC normalization ensures that composed and decomposed forms (e.g. `é` vs `e` + U+0301) produce identical output.
